//! Per-OS errno text tables generated by `anthology-dev gen-errno` (P1, GC-16 I-10).
//!
//! `linux_glibc` was dumped in the pinned Python 3.12 image and `macos` on macOS, both by
//! `port/difftest/oracle/errno_dump.py`. [`strerror`] picks this build's OS: macOS on macOS,
//! glibc Linux everywhere else, musl builds included, so users see the text Python printed on
//! glibc Linux and macOS (design §12, architect's call). Never libc `strerror` or
//! `io::Error`'s `Display`.

pub mod linux_glibc;
pub mod macos;

/// One OS's table.
#[derive(Clone, Copy, Debug)]
pub struct Table {
    pub text: &'static [&'static str],
    pub unknown_prefix: &'static str,
}

/// The glibc Linux table.
pub const LINUX_GLIBC: Table = Table {
    text: linux_glibc::TEXT,
    unknown_prefix: linux_glibc::UNKNOWN_PREFIX,
};

/// The macOS table.
pub const MACOS: Table = Table {
    text: macos::TEXT,
    unknown_prefix: macos::UNKNOWN_PREFIX,
};

/// This build's table.
pub const HOST: Table = if cfg!(target_os = "macos") {
    MACOS
} else {
    LINUX_GLIBC
};

impl Table {
    /// `os.strerror(n)` on this table's OS.
    pub fn strerror(&self, n: i32) -> String {
        match usize::try_from(n).ok().and_then(|i| self.text.get(i)) {
            Some(t) => (*t).to_string(),
            None => format!("{}{n}", self.unknown_prefix),
        }
    }
}

/// `os.strerror(n)` as Python printed it on this OS.
pub fn strerror(n: i32) -> String {
    HOST.strerror(n)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn both_tables_hold_the_os_texts() {
        assert_eq!(LINUX_GLIBC.strerror(2), "No such file or directory");
        assert_eq!(LINUX_GLIBC.strerror(0), "Success");
        assert_eq!(LINUX_GLIBC.strerror(133), "Memory page has hardware error");
        assert_eq!(LINUX_GLIBC.strerror(134), "Unknown error 134");
        assert_eq!(LINUX_GLIBC.strerror(-1), "Unknown error -1");
        assert_eq!(MACOS.strerror(0), "Undefined error: 0");
        assert_eq!(MACOS.strerror(13), "Permission denied");
        assert_eq!(MACOS.strerror(106), "Interface output queue is full");
        assert_eq!(MACOS.strerror(9999), "Unknown error: 9999");
        assert!(LINUX_GLIBC.text.len() > 133 && MACOS.text.len() > 106);
    }

    #[test]
    fn the_host_table_follows_the_target_os() {
        let want = if cfg!(target_os = "macos") {
            "Unknown error: 500"
        } else {
            "Unknown error 500"
        };
        assert_eq!(strerror(500), want);
    }
}
